import * as fs from 'fs-extra';
import * as path from 'path';

import escapeRegExp = require('lodash.escaperegexp');
import * as vscode from 'vscode';

import * as filepaths from './managers/filepaths';
import * as promptUtils from './utils/prompt';

import { IPluginSettings } from './types';

/**
 * Open file after duplicate action.
 */
async function openFile(filepath: string): Promise<vscode.TextEditor> {
	const document = await (vscode.workspace.openTextDocument(filepath) as Promise<vscode.TextDocument>);

	return vscode.window.showTextDocument(document);
}

/**
 * Duplicate action.
 */
async function duplicator(uri: vscode.Uri, settings: IPluginSettings): Promise<vscode.TextEditor | undefined> {
	const oldPath = uri.fsPath;
	const oldPathParsed = path.parse(oldPath);
	const oldPathStats = await fs.stat(oldPath);

	// Get a new name for the resource
	const newName = await promptUtils.name(oldPathParsed.name);
	if (!newName) {
		return;
	}

	// Get the new full path
	const newPath = filepaths.buildFilepath(oldPathParsed, oldPathStats, newName, settings);

	// If a user tries to copy a file on the same path
	if (uri.fsPath === newPath) {
		vscode.window.showErrorMessage('You can\'t copy a file or directory on the same path.');

		return;
	}

	// Check if the current path exists
	const newPathExists = await fs.pathExists(newPath);
	if (newPathExists) {
		const userAnswer = await promptUtils.overwrite(newPath);
		if (!userAnswer) {
			return;
		}
	}

	try {
		await fs.copy(uri.fsPath, newPath);

		if (settings.openFileAfterCopy && oldPathStats.isFile()) {
			return openFile(newPath);
		}
	} catch (err) {
		const errMsgRegExp = new RegExp(escapeRegExp(oldPathParsed.dir), 'g');
		const errMsg = err.message
			.replace(errMsgRegExp, '')
			.replace(/[\\|\/]/g, '')
			.replace(/`|'/g, '**');

		vscode.window.showErrorMessage(`Error: ${errMsg}`);
	}

	return;
}

export function activate(context: vscode.ExtensionContext): void {
	const command = vscode.commands.registerCommand('duplicate.execute', (uri: vscode.TextDocument | vscode.Uri) => {
		const settings = vscode.workspace.getConfiguration().get('duplicate') as IPluginSettings;

		if (!uri || !(<vscode.Uri>uri).fsPath) {
			const editor = vscode.window.activeTextEditor;
			if (!editor) {
				return;
			}

			return duplicator(<vscode.Uri>editor.document.uri, settings);
		}

		return duplicator(<vscode.Uri>uri, settings);
	});

	context.subscriptions.push(command);
}

import * as assert from 'assert';
import * as path from 'path';

import * as manager from './filepaths';

function getBuildedFilepath(oldName: string, newName: string, isFile: boolean, keep: boolean): string {
	const oldPath = path.parse(`/Users/name/Documents/${oldName}`);

	return manager.buildFilepath(
		oldPath,
		{ isFile: () => isFile } as any, /* tslint:disable-line no-any */
		newName,
		{ keepOriginalExtension: keep, openFileAfterCopy: false }
	);
}

describe('Managers → Filepaths', () => {
	describe('.buildFilepath', () => {
		it('should build path to file', () => {
			const expected = '/Users/name/Documents/test.ts';

			const actual = getBuildedFilepath('test.js', 'test.ts', true, true);

			assert.equal(actual, expected);
		});

		it('should build path to directory', () => {
			const expected = '/Users/name/Documents/test-copy';

			const actual = getBuildedFilepath('test', 'test-copy', false, true);

			assert.equal(actual, expected);
		});

		it('should add original extension for new path of non-dot file', () => {
			const expected = '/Users/name/Documents/test.js';

			const actual = getBuildedFilepath('test.js', 'test', true, true);

			assert.equal(actual, expected);
		});

		it('should not add original extension for new path of non-dot file', () => {
			const expected = '/Users/name/Documents/test';

			const actual = getBuildedFilepath('test.js', 'test', false, true);

			assert.equal(actual, expected);
		});

		it('should add original extension for new path of dot file', () => {
			const expected = '/Users/name/Documents/.env.sample';

			const actual = getBuildedFilepath('.env.sample', '.env', true, true);

			assert.equal(actual, expected);
		});

		it('should not add original extension for new path of dot file', () => {
			const expected = '/Users/name/Documents/.env';

			const actual = getBuildedFilepath('.env.sample', '.env', true, false);

			assert.equal(actual, expected);
		});

		it('should not add original extension for new path of dot file with !!ext marker', () => {
			const expected = '/Users/name/Documents/.env';

			const actual = getBuildedFilepath('.env.sample', '.env!!ext', true, true);

			assert.equal(actual, expected);
		});

		it('should add original extension for new path of dot file with &&ext marker', () => {
			const expected = '/Users/name/Documents/.env.sample';

			const actual = getBuildedFilepath('.env.sample', '.env&&ext', true, false);

			assert.equal(actual, expected);
		});
	});
});

import * as fs from 'fs';
import * as path from 'path';

import { IPluginSettings } from '../types';

export function buildFilepath(oldPath: path.ParsedPath, oldStat: fs.Stats, newName: string, settings: IPluginSettings): string {
	const newPath = path.parse(newName);

	// Check ability to add original extension
	const needAddExtension = (settings.keepOriginalExtension && !newName.endsWith('!!ext')) || newName.endsWith('&&ext');

	// Clean the new name from special characters
	let newStripedName = newName.replace(/(!!|&&)ext$/, '');

	// The new path has no extension and we must save original extension
	if (oldStat.isFile() && newPath.ext === '' && needAddExtension) {
		newStripedName += oldPath.ext;
	}

	return path.join(oldPath.dir, newStripedName);
}

export interface IPluginSettings {
	openFileAfterCopy: boolean;
	keepOriginalExtension: boolean;
}

import * as vscode from 'vscode';

export function name(filename: string): Promise<string | undefined> {
	return vscode.window.showInputBox({
		placeHolder: 'Enter the new path for the duplicate.',
		value: filename.split('.').map((el, i) => i === 0 ? `${el}-copy` : el).join('.')
	}) as Promise<string | undefined>;
}

export function overwrite(filepath: string): Promise<vscode.MessageItem | undefined> {
	const message = `The path **${filepath}** alredy exists. Do you want to overwrite the existing path?`;
	const action = {
		title: 'OK',
		isCloseAffordance: false
	};

	return vscode.window.showWarningMessage(message, action) as Promise<vscode.MessageItem | undefined>;
}

